// Hand-written entry point. The pipeline copies this file to
// app_dart/web/main.dart; a same-named .ts would be skipped, and there is none.
//
// For reference, the Angular 2 era TypeScript entry looked like this:
//
//   import {bootstrap} from 'angular2/platform/browser';
//   import {FileDropApp} from './file_drop_app';
//   export function main() { bootstrap(FileDropApp); }
//
// AngularDart replaced that bootstrap API with runApp(<factory>), and the
// factory is generated by the Angular compiler (file_drop_app.template.dart).
import 'package:ngdart/angular.dart';
import 'package:webdrop_frontend/file_drop_app.dart';
import 'package:webdrop_frontend/file_drop_app.template.dart' as ng;

void main() {
  runApp<FileDropApp>(ng.FileDropAppNgFactory);
}
